    "Website SEO data (free: Open PageRank)": "Données SEO du site (gratuit : Open PageRank)",
    "Free: get a key at openpagerank.keywordseverywhere.com/dashboard (sign in with a Keywords Everywhere key; old DomCop keys no longer work). It gives a 0-10 authority score and the world rank of a lead website. Used when no Ahrefs or Ubersuggest key answers. The basic SEO checks (title, description, mobile, indexing, robots.txt, sitemap) need no key at all.": "Gratuit : obtenez une clé sur openpagerank.keywordseverywhere.com/dashboard (un compte suffit). Elle donne une note d'autorité de 0 à 10 et le rang mondial du site d'un lead. Utilisée si aucune clé Ahrefs ou Ubersuggest ne répond. Les contrôles SEO de base (titre, description, mobile, indexation, robots.txt, sitemap) n'ont besoin d'aucune clé.",
    "Open PageRank API key": "Clé API Open PageRank",
    "World rank": "Rang mondial",
    "SEO basics": "SEO de base",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ahrefs, Ubersuggest or free Open PageRank key is saved in Settings → AI.": "Les chiffres SEO (autorité, trafic, mots-clés, backlinks) apparaissent ici dès qu'une clé Ahrefs, Ubersuggest ou Open PageRank (gratuite) est enregistrée dans Réglages → IA.",
    "Website SEO data (Ahrefs)": "Données SEO du site (Ahrefs)",
    "With your Ahrefs API key (API v3), hovering the website of a lead shows its domain rating, organic traffic and keywords, and backlinks. When both keys are saved, Ahrefs is used. The key is stored encrypted and never shown again.": "Avec votre clé API Ahrefs (API v3), survoler le site web d'un lead affiche son Domain Rating, son trafic et ses mots-clés organiques, et ses backlinks. Si les deux clés sont enregistrées, Ahrefs est utilisé. La clé est stockée chiffrée et jamais réaffichée.",
    "Ahrefs API key": "Clé API Ahrefs",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ahrefs or Ubersuggest key is saved in Settings → AI.": "Les chiffres SEO (autorité, trafic, mots-clés, backlinks) apparaissent ici dès qu'une clé Ahrefs ou Ubersuggest est enregistrée dans Réglages → IA.",
