    "From Meta for Developers → WhatsApp → API setup: the phone number ID and a permanent access token. Outside a 24 hour conversation WhatsApp only delivers approved templates: give the name of a template with one body variable and its language, or leave it empty for plain messages.": "Depuis Meta for Developers → WhatsApp → Configuration de l'API : l'ID du numéro de téléphone et un jeton d'accès permanent. Hors d'une conversation de 24 h, WhatsApp ne livre que des modèles approuvés : indiquez le nom d'un modèle avec une variable de corps et sa langue, ou laissez vide pour des messages simples.",
