    "Every payroll payment that has no expense yet gets one in the Payroll category. Payments that already have one are not touched. Expenses entered by hand are never changed.": "Chaque paiement de paie sans dépense en reçoit une dans la catégorie Paie. Les paiements qui en ont déjà une ne sont pas modifiés. Les dépenses saisies à la main ne sont jamais changées.",
    "{n} expenses created": "{n} dépenses créées",
    "Payroll and expenses": "Paie et dépenses",
    "Record payroll payments as expenses": "Enregistrer les paiements de paie comme dépenses",
    "Salaries, advances and bonuses recorded in Payroll can also appear as expenses (category \"Payroll\"), so expense and profit reports include the team cost. Do not turn this on if you already enter salaries as expenses yourself.": "Les salaires, avances et primes enregistrés dans Paie peuvent aussi apparaître comme dépenses (catégorie « Paie »), pour que les rapports de dépenses et de bénéfices incluent le coût de l'équipe. Ne l'activez pas si vous saisissez déjà les salaires comme dépenses.",
    "New, edited and deleted payments update their expense. Existing payments are added with the button below.": "Les paiements nouveaux, modifiés et supprimés mettent à jour leur dépense. Les paiements existants s'ajoutent avec le bouton ci-dessous.",
    "Existing payroll payments": "Paiements de paie existants",
    "Turn the switch above on and save first. Then create the expenses of the payments already recorded in Payroll (only those that have none yet).": "Activez d'abord l'interrupteur ci-dessus et enregistrez. Créez ensuite les dépenses des paiements déjà enregistrés dans Paie (seulement ceux qui n'en ont pas encore).",
    "Offline · last seen {when}": "Hors ligne · vu le {when}",
    "Due: {month}": "À payer : {month}",
    "Paid for {month}": "Payé pour {month}",
    "Paid on day {n} of the next month": "Payé le {n} du mois suivant",
    "Still to pay for {month}": "Reste à payer pour {month}",
    "To pay: {month}": "À payer : {month}",
    "Salaries are paid after the month": "Les salaires sont payés après le mois",
    "A month shows as due from the 1st of the next month and is paid on the pay day of that month (October on 1 November, paid on the 10th). Turn off to pay and show the current month.": "Un mois devient dû à partir du 1er du mois suivant et est payé le jour de paie de ce mois (octobre le 1er novembre, payé le 10). Désactivez pour payer et afficher le mois en cours.",
    "Inactive: switch on to edit this member": "Inactif : activez pour modifier ce membre",
    "makes a video room on meet.trtcrm.com. For Google Meet use": "crée une salle vidéo sur meet.trtcrm.com. Pour Google Meet, utilisez",
    "Back to the original": "Revenir à l'original",
    "Pick a colour": "Choisir une couleur",
    "Save statuses": "Enregistrer les statuts",
    "Statuses back to the original names and colours": "Statuts revenus aux noms et couleurs d'origine",
    "Statuses saved": "Statuts enregistrés",
    "Task statuses": "Statuts des tâches",
    "Rename the five statuses and pick their colours. The board columns, the list, the calendar, the timeline and the dashboard follow. Existing tasks keep their status.": "Renommez les cinq statuts et choisissez leurs couleurs. Le tableau, la liste, le calendrier, la chronologie et le tableau de bord suivent. Les tâches existantes gardent leur statut.",
    "A status colour must look like #3b82f6": "La couleur d'un statut doit ressembler à #3b82f6",
    "Two statuses cannot have the same name": "Deux statuts ne peuvent pas avoir le même nom",
    "The columns of the Tasks board. Type to rename, pick a colour, drag to reorder, add a row for a new status. New tasks start as Not started; the app needs Not started, In progress and Complete, so those cannot be deleted. Deleting another one sends its tasks back to Not started.": "Les colonnes du tableau des tâches. Tapez pour renommer, choisissez une couleur, glissez pour réorganiser, ajoutez une ligne pour un nouveau statut. Les nouvelles tâches commencent à « Non commencée » ; l'application a besoin de Non commencée, En cours et Terminée, qui ne peuvent donc pas être supprimées. Supprimer un autre statut renvoie ses tâches à « Non commencée ».",
    "This status is used by the app (new tasks, timers, finished tasks) and cannot be deleted. Rename or recolour it instead.": "Ce statut est utilisé par l'application (nouvelles tâches, chronomètres, tâches terminées) et ne peut pas être supprimé. Renommez-le ou changez sa couleur.",
    "The columns of the Tasks board and the names you see on every task.": "Les colonnes du tableau des tâches et les noms que vous voyez sur chaque tâche.",
    "In use": "Utilisé",
    "Not used": "Non utilisé",
    "Records using it": "Éléments qui l'utilisent",
    "Only an administrator can use the mail server settings": "Seul un administrateur peut utiliser les paramètres du serveur de messagerie",
    "A currency has no rate, so its amounts are left out. Set the rate in Settings → Currencies.": "Une devise n'a pas de taux : ses montants sont ignorés. Définissez le taux dans Paramètres → Devises.",
