    "Name, email, phone, company, website, city and message are recognised in English, French, Spanish and Arabic. Add your own labels only if a field is missed. Anything not recognised is kept in the lead's description.": "Le nom, l'e-mail, le téléphone, la société, le site web, la ville et le message sont reconnus en anglais, français, espagnol et arabe. Ajoutez vos propres libellés seulement si un champ est manqué. Ce qui n'est pas reconnu est conservé dans la description du prospect.",
    "Names used in your forms": "Libellés utilisés dans vos formulaires",
    "New mailbox": "Nouvelle boîte mail",
    "No server yet": "Pas encore de serveur",
    "Nobody": "Personne",
    "Not checked yet": "Pas encore vérifiée",
    "Only emails that match every filter you fill in become leads. Everything else stays untouched in the mailbox. Separate several words with commas.": "Seuls les e-mails qui correspondent à chaque filtre renseigné deviennent des prospects. Tout le reste reste intact dans la boîte mail. Séparez plusieurs mots par des virgules.",
    "Only look at unread emails": "Ne regarder que les e-mails non lus",
    "Open lead": "Ouvrir le prospect",
    "Pick the source, status and the person who follows up, then use Preview to see how the latest emails would be read.": "Choisissez la source, le statut et la personne qui assure le suivi, puis utilisez Aperçu pour voir comment les derniers e-mails seraient lus.",
    "Preview: the last emails": "Aperçu : les derniers e-mails",
    "Read emails received since": "Lire les e-mails reçus depuis",
