    "No backup yet.": "Aucune sauvegarde pour le moment.",
    "There is no backup yet.": "Il n'y a pas encore de sauvegarde.",
    "The file storage (DigitalOcean Spaces) is not set up, so there is nowhere to put the backups.": "Le stockage de fichiers (DigitalOcean Spaces) n'est pas configuré : les sauvegardes n'ont nulle part où aller.",
    "The last good backup is older than a day and a half.": "La dernière bonne sauvegarde date de plus d'un jour et demi.",
    "To restore a file, download it and run: node scripts/restore-backup.mjs <file> (add --apply to write).": "Pour restaurer un fichier, téléchargez-le et lancez : node scripts/restore-backup.mjs <fichier> (ajoutez --apply pour écrire).",
    "Your administrator requires two-step sign-in. Turn on the authenticator app or the email code below to keep using the CRM.": "Votre administrateur exige la connexion en deux étapes. Activez l'application d'authentification ou le code par email ci-dessous pour continuer à utiliser le CRM.",
    "Your administrator requires two-step sign-in: turn it on in your profile, Security, to continue.": "Votre administrateur exige la connexion en deux étapes : activez-la dans votre profil, Sécurité, pour continuer.",
    "Two-step sign-in": "Connexion en deux étapes",
    "Required for": "Obligatoire pour",
    "Nobody (optional for everyone)": "Personne (facultatif pour tous)",
    "Administrators and people who see the vault, payments or payroll": "Administrateurs et personnes qui voient le coffre, les paiements ou la paie",
    "Make the second step (authenticator app or email code) compulsory. Someone the rule covers who has not turned it on can only open their profile, Security, until they do. Everybody can always turn it on themselves.": "Rendez la deuxième étape (application d'authentification ou code par email) obligatoire. Une personne concernée qui ne l'a pas activée ne peut ouvrir que son profil, Sécurité, tant qu'elle ne l'a pas fait. Chacun peut toujours l'activer lui-même.",
    "Backups": "Sauvegardes",
    "Backup files": "Fichiers de sauvegarde",
    "Back up the database every night": "Sauvegarder la base de données chaque nuit",
    "Every night after 02:00 (company time) the whole database is saved to the file storage: the last 14 days and one a week for 12 weeks. It does not need the automatic tasks to be on.": "Chaque nuit après 02h00 (heure de l'entreprise), toute la base de données est enregistrée dans le stockage de fichiers : les 14 derniers jours et une par semaine pendant 12 semaines. Les tâches automatiques n'ont pas besoin d'être activées.",
    "Alerts": "Alertes",
    "Send alerts to the administrators": "Envoyer des alertes aux administrateurs",
    "The administrators are told (bell, email, Telegram / WhatsApp) when a backup fails or is late, when the automatic tasks stop or report errors, and when the CRM returns a burst of server errors. The same alert is sent once an hour at most.": "Les administrateurs sont prévenus (cloche, email, Telegram / WhatsApp) quand une sauvegarde échoue ou est en retard, quand les tâches automatiques s'arrêtent ou signalent des erreurs, et quand le CRM renvoie une rafale d'erreurs serveur. La même alerte est envoyée au plus une fois par heure.",
