    "Day · hours · team members who take the meetings that day": "Jour · heures · membres de l'équipe qui prennent les réunions ce jour-là",
    "Weekly schedule: who takes meetings, which days and hours": "Planning de la semaine : qui prend les réunions, quels jours et quelles heures",
    "Tick the days people can book, set the hours of each day (10-13,14-17 = 10:00 to 13:00 and 14:00 to 17:00, 24-hour clock) and choose the team members who take the meetings that day. A visitor is offered a time only when at least one of them is free, and the meeting is given to the one who is free. No one chosen = the team members below.": "Cochez les jours réservables, réglez les heures de chaque jour (10-13,14-17 = de 10h à 13h et de 14h à 17h, format 24 h) et choisissez les membres qui prennent les réunions ce jour-là. Un horaire n'est proposé que si l'un d'eux est libre, et la réunion est confiée à celui qui est libre. Personne de choisi = l'équipe ci-dessous.",
    "Default team for the meetings": "Équipe par défaut pour les réunions",
    "Used for a day with nobody chosen in the weekly schedule. They are told about each request and can accept or refuse it. Empty = every administrator.": "Utilisée pour un jour sans personne choisie dans le planning. Ils sont prévenus de chaque demande et peuvent l'accepter ou la refuser. Vide = tous les administrateurs.",
