    "Adds the articles that explain every page of the client area (invoices, estimates, proposals, contracts, projects, tasks, ideas, requests, support, profile...) in each language in use. If the guide is already there, its articles are refreshed; your own articles are not touched.": "Ajoute les articles qui expliquent chaque page de l'espace client (factures, devis, propositions, contrats, projets, tâches, idées, demandes, support, profil...) dans chaque langue utilisée. Si le guide est déjà là, ses articles sont actualisés ; vos propres articles ne sont pas touchés.",
