    "Side jobs paid like invoices, without numbers. They stay out of the company dashboard, reports and goals.": "Travaux annexes payés comme des factures, sans numéro. Ils restent hors du tableau de bord, des rapports et des objectifs de l'entreprise.",
    "The job is removed for good. If it repeats, the payments already created stay.": "Le travail est supprimé définitivement. S'il se répète, les paiements déjà créés restent.",
    "The next payment is created automatically when it is due (a monthly retainer, hosting...)": "Le prochain paiement est créé automatiquement à l'échéance (forfait mensuel, hébergement...)",
