    "API and webhooks": "API et webhooks",
    "Two ways to talk to the CRM from outside, both secure: keys to read and push data, webhooks to be told when something happens.": "Deux façons de parler au CRM depuis l'extérieur, toutes deux sécurisées : des clés pour lire et envoyer des données, des webhooks pour être prévenu quand quelque chose arrive.",
    "API keys": "Clés API",
    "Webhooks": "Webhooks",
    "How to use": "Mode d'emploi",
    "New API key": "Nouvelle clé API",
    "An API key lets another program (a website form, n8n, Zapier, your own code) read or push data. Give each program its own key with only what it needs, and revoke it when it is not used any more.": "Une clé API permet à un autre programme (un formulaire de site, n8n, Zapier, votre code) de lire ou d'envoyer des données. Donnez à chaque programme sa propre clé avec seulement ce dont il a besoin, et révoquez-la quand elle ne sert plus.",
