    "The program that uses \"{name}\" stops working at once. This cannot be undone.": "Le programme qui utilise « {name} » s'arrête aussitôt. Action irréversible.",
    "A webhook is the other direction: when something happens in the CRM (a lead arrives, a task is created…) the CRM calls the address you give, with the data, signed so that your program can check it really comes from here.": "Un webhook va dans l'autre sens : quand quelque chose arrive dans le CRM (un prospect arrive, une tâche est créée…), le CRM appelle l'adresse que vous donnez, avec les données, signées pour que votre programme vérifie qu'elles viennent bien d'ici.",
