    "Copy it now, it is shown only once. Your program uses it to check the signature of every call.": "Copiez-le maintenant, il n'est affiché qu'une fois. Votre programme l'utilise pour vérifier la signature de chaque appel.",
    "Delete this webhook?": "Supprimer ce webhook ?",
    "Webhook deleted": "Webhook supprimé",
    "Send your key": "Envoyez votre clé",
    "Every call carries the key in a header. Answers are JSON. Limit: 120 calls a minute per key.": "Chaque appel porte la clé dans un en-tête. Les réponses sont en JSON. Limite : 120 appels par minute et par clé.",
    "Resources": "Ressources",
    "Resource": "Ressource",
    "Create / change": "Création / modification",
    "Lists take ?limit= (up to 100), ?page=, ?q= (search) and ?updated_since= (ISO date), and answer { data, page, limit, total }.": "Les listes acceptent ?limit= (jusqu'à 100), ?page=, ?q= (recherche) et ?updated_since= (date ISO), et répondent { data, page, limit, total }.",
    "Push a lead (for example from a website form)": "Envoyer un prospect (par exemple depuis un formulaire de site)",
    "Push an idea to the Grow board": "Envoyer une idée au tableau Grow",
    "Check a webhook call": "Vérifier un appel de webhook",
    "Each call has the headers X-TRT-Event and X-TRT-Signature (t=<seconds>,v1=<hmac>). Recompute the HMAC SHA-256 of \"<t>.<raw body>\" with your signing secret and compare. Refuse calls whose t is older than 5 minutes.": "Chaque appel porte les en-têtes X-TRT-Event et X-TRT-Signature (t=<secondes>,v1=<hmac>). Recalculez le HMAC SHA-256 de « <t>.<corps brut> » avec votre secret et comparez. Refusez les appels dont t date de plus de 5 minutes.",
