    "Copy the secret now. It is shown only once: if you lose it, create a new one.": "Copiez le secret maintenant. Il n'est affiché qu'une fois : si vous le perdez, créez-en un nouveau.",
    "Delete this app?": "Supprimer cette application ?",
    "Let another app of yours (the Meet app) sign the team in with their CRM account. Only active team members can sign in: clients never. Guests of a meeting use the meeting link and are admitted by a team member.": "Laissez une autre de vos applications (Meet) connecter l'équipe avec son compte CRM. Seuls les membres actifs de l'équipe peuvent se connecter : jamais les clients. Les invités d'une réunion utilisent le lien et sont admis par un membre de l'équipe.",
