    "Ways to talk to the CRM from outside, all secure: keys to read and push data, webhooks to be told when something happens, and sign-in for your other apps.": "Des moyens sûrs de parler au CRM depuis l'extérieur : des clés pour lire et envoyer des données, des webhooks pour être prévenu, et la connexion pour vos autres applications.",
    "What the app learns about the person: id, name, email, photo, staff id, whether they are an administrator and their role. Any OpenID Connect library works with the discovery address.": "Ce que l'application apprend de la personne : identifiant, nom, e-mail, photo, identifiant du membre, si elle est administratrice et son rôle. Toute bibliothèque OpenID Connect fonctionne avec l'adresse de découverte.",
