    "It goes out at the first run of the automatic tasks after that time (Settings → Cron job), so they must run often, for example every 5 minutes.": "Il part au premier passage des tâches automatiques après cette heure (Paramètres → Cron job) : elles doivent donc tourner souvent, par exemple toutes les 5 minutes.",
