    "Appointment accepted": "Rendez-vous accepté",
    "Appointment declined": "Rendez-vous refusé",
    "Appointment request: waiting for you": "Demande de rendez-vous : en attente de votre réponse",
    "Nobody is invited and no reminder goes out until you accept. The person who asked is told by email.": "Personne n'est invité et aucun rappel n'est envoyé tant que vous n'acceptez pas. La personne qui a demandé est prévenue par e-mail.",
    "Send an appointment request to the calendar": "Envoyer une demande de rendez-vous au calendrier",
    "The key needs the scope “Send appointment requests”. The request is a draft on the calendar (⏳): nobody is invited and no reminder goes out until a team member accepts it. The same room is never recorded twice. Ask its state with GET /calendar/events/<id>, or subscribe to the webhooks appointment.accepted and appointment.declined.": "La clé doit avoir la portée « Envoyer des demandes de rendez-vous ». La demande est un brouillon dans le calendrier (⏳) : personne n'est invité et aucun rappel n'est envoyé tant qu'un membre de l'équipe ne l'accepte pas. La même salle n'est jamais enregistrée deux fois. Demandez son état avec GET /calendar/events/<id>, ou abonnez-vous aux webhooks appointment.accepted et appointment.declined.",
    "confirmation sent": "confirmation envoyée",
    "Send appointment requests to the calendar (they wait for acceptance)": "Envoyer des demandes de rendez-vous au calendrier (elles attendent l'acceptation)",
    "An appointment is requested (waiting for acceptance)": "Un rendez-vous est demandé (en attente d'acceptation)",
    "An appointment request is accepted": "Une demande de rendez-vous est acceptée",
    "An appointment request is declined": "Une demande de rendez-vous est refusée",
    "An appointment lasts 12 hours at most": "Un rendez-vous dure 12 heures au maximum",
