    "Every certificate, language exam or course you pass gives points and can win a trophy with a cash prize between 200 and 1000 MAD, on top of the prime of the goal. Pick a goal in the Catalog and ask for approval: the first step is the easiest.": "Chaque certificat, examen de langue ou formation réussi donne des points et peut gagner un trophée avec un prix en espèces de 200 à 1000 MAD, en plus de la prime de l'objectif. Choisissez un objectif dans le Catalogue et demandez l'approbation : le premier pas est le plus facile.",
