    "Answer by": "Répondre avant le",
    "Anything the AI should know or focus on (optional)": "Ce que l'IA doit savoir ou privilégier (facultatif)",
    "Assign team members…": "Assigner des membres de l'équipe…",
    "Cannot search the web with this provider: add the competitors below, or choose Claude in Settings → AI for live research.": "Ce fournisseur ne peut pas chercher sur le web : indiquez les concurrents ci-dessous, ou choisissez Claude dans Paramètres → IA pour une recherche en direct.",
    "Client answer": "Réponse du client",
    "Competitor benchmark": "Benchmark des concurrents",
