    "No AI key yet. Add one in Settings → AI, then come back.": "Pas encore de clé IA. Ajoutez-en une dans Paramètres → IA, puis revenez.",
    "No idea for this client yet. Write one, or let the AI study the client and its competitors and suggest what is worth proposing.": "Aucune idée pour ce client. Écrivez-en une, ou laissez l'IA étudier le client et ses concurrents et suggérer ce qui vaut la peine d'être proposé.",
    "No message yet": "Aucun message",
    "Nothing goes to the client: you pick the ideas and they become drafts.": "Rien n'est envoyé au client : vous choisissez les idées et elles deviennent des brouillons.",
    "Only the team can see it": "Seule l'équipe peut la voir",
    "Our opening": "Notre ouverture",
    "Our service": "Notre service",
    "Price": "Prix",
    "Price (optional)": "Prix (facultatif)",
    "Proposes only ideas we can deliver with our services and prices, each with its evidence, plan, gain and effort.": "Ne propose que des idées que nous pouvons réaliser avec nos services et nos prix, chacune avec ses preuves, son plan, son gain et son effort.",
    "Questions and answers between you and the client appear here.": "Les questions et réponses entre vous et le client apparaissent ici.",
    "Reads what we sold this client, its projects, support subjects, proposals and the ideas already written.": "Lit ce que nous avons vendu à ce client, ses projets, sujets de support, propositions et les idées déjà écrites.",
    "Research": "Rechercher",
    "Researching… this can take up to two minutes when the AI searches the web.": "Recherche en cours… cela peut prendre jusqu'à deux minutes quand l'IA cherche sur le web.",
    "Saved. {n} email(s) sent to the client.": "Enregistré. {n} e-mail(s) envoyé(s) au client.",
    "Saving with the status Proposed shows the idea in the client area and emails the client's contacts.": "Enregistrer avec le statut Proposé affiche l'idée dans l'espace client et envoie un e-mail aux contacts du client.",
    "Search again": "Rechercher à nouveau",
