    "Searches the web for its business and its closest competitors, and compares them with the client.": "Cherche sur le web son activité et ses concurrents les plus proches, et les compare avec le client.",
    "Sent to {ai}: the company name, website and industry, what we invoiced and sold, project and support subjects. No contact names, emails or phone numbers.": "Envoyé à {ai} : le nom de l'entreprise, son site et son secteur, ce que nous avons facturé et vendu, les sujets de projets et de support. Aucun nom de contact, e-mail ou téléphone.",
    "Sources found by the AI": "Sources trouvées par l'IA",
