    "ideas": "idées",
    "seo, ads, site (separated by commas)": "seo, pub, site (séparés par des virgules)",
    "waiting for the client": "en attente du client",
    "with web search": "avec recherche web",
    "{n} idea(s) added as drafts": "{n} idée(s) ajoutée(s) en brouillon",
