    "this device": "cet appareil",
    "This device": "Cet appareil",
    "Push notifications on phones and computers": "Notifications push sur téléphones et ordinateurs",
    "Send push notifications to phones and computers": "Envoyer des notifications push aux téléphones et ordinateurs",
    "Everybody can install the app on their phone (Android: Install; iPhone: Share → Add to Home Screen) and switch notifications on from the profile menu → Install the app. Each bell notification and each private chat message then appears on the screen of the phone, even when the app is closed. Off stops all of them.": "Chacun peut installer l'application sur son téléphone (Android : Installer ; iPhone : Partager → Sur l'écran d'accueil) et activer les notifications depuis le menu du profil → Installer l'application. Chaque notification de la cloche et chaque message privé apparaît alors sur l'écran du téléphone, même application fermée. Désactivé les arrête toutes.",
    "Everyone edits their own events, the events they are invited to and public events": "Chacun modifie ses événements, ceux auxquels il est invité et les événements publics",
    "Everyone deletes their own events, the events they are invited to and public events": "Chacun supprime ses événements, ceux auxquels il est invité et les événements publics",
    "Add pictures, record a voice note or attach a file. Pictures can also be pasted in the text.": "Ajoutez des images, enregistrez une note vocale ou joignez un fichier. Les images peuvent aussi être collées dans le texte.",
    "Blue": "Bleu",
    "Colour and labels": "Couleur et étiquettes",
