    "You are not allowed to send or schedule mails": "Vous n'avez pas le droit d'envoyer ou de programmer des mails",
    "The Mails tab of a client, for the clients the person can see. Create = write a draft or log a mail; Edit = change a mail or a draft; Send = send a draft now or schedule it; Delete = remove a mail. Changing or removing a mail written by someone else also needs the matching right on Customers.": "L'onglet Mails d'un client, pour les clients que la personne voit. Créer = écrire un brouillon ou noter un mail ; Modifier = changer un mail ou un brouillon ; Envoyer = envoyer un brouillon ou le programmer ; Supprimer = retirer un mail. Modifier ou retirer le mail de quelqu'un d'autre demande aussi le droit correspondant sur Clients.",
    "The Mails tab of a lead, for the leads the person can see. Create = write a draft or log a mail; Edit = change a mail or a draft; Send = send a draft now or schedule it; Delete = remove a mail. Changing or removing a mail written by someone else also needs the matching right on Leads.": "L'onglet Mails d'un prospect, pour les prospects que la personne voit. Créer = écrire un brouillon ou noter un mail ; Modifier = changer un mail ou un brouillon ; Envoyer = envoyer un brouillon ou le programmer ; Supprimer = retirer un mail. Modifier ou retirer le mail de quelqu'un d'autre demande aussi le droit correspondant sur Prospects.",
